<?php require __DIR__.'/bootstrap.php';require __DIR__.'/layout.php';$u=require_login();$message='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$q=$db->prepare('SELECT password_hash FROM usuarios WHERE id=?');$q->execute([$u['id']]);$hash=$q->fetchColumn();$new=(string)($_POST['new_password']??'');if(!password_verify((string)($_POST['current_password']??''),$hash))$error='La contraseña actual no es correcta.';elseif(strlen($new)<10||$new!==($_POST['repeat_password']??''))$error='La nueva contraseña debe tener al menos 10 caracteres y coincidir.';else{$hash=password_hash($new,PASSWORD_DEFAULT);$db->prepare("UPDATE usuarios SET password_hash=?,password_status='CHANGED',password_changed_at=NOW(),password_changed_by=? WHERE id=?")->execute([$hash,$u['id'],$u['id']]);audit($db,$u['id'],$u['username'],'PASSWORD_CHANGED','USUARIO',$u['id']);$message='Contraseña actualizada correctamente.';}}page_start('Mi cuenta',$u);?><section class="panel narrow"><?php if($message):?><div class="alert success"><?=e($message)?></div><?php endif;if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Contraseña actual<input type="password" name="current_password" required></label><label>Nueva contraseña<input type="password" name="new_password" required minlength="10"></label><label>Repetir contraseña<input type="password" name="repeat_password" required minlength="10"></label><button class="primary">Cambiar contraseña</button></form></section><?php page_end();

